void Solver::bump_var(int var, double coeff) {
    if (coeff <= 0.0) return;
    const double MAX_ACT = 1e100;
    const double RESCALE = 1e-100;
    double inc = var_inc * coeff;
    double &act = activity[var];
    act += inc;
    if (act > MAX_ACT) {
        for (int i = 1; i <= vars; ++i) activity[i] *= RESCALE;
        var_inc *= RESCALE;
    }
    if (vsids.inHeap(var)) vsids.update(var);
}
